css:
:root{
  --green-900:#122f22; --green-800:#183a2a; --green-700:#1f4a35; --green-600:#2e7d4f; --green-500:#3a9d63;
  --gold:#e0a72e; --gold-dark:#c8901f;
  --ink:#16241c; --body:#33413a; --muted:#6b7b72;
  --bg:#f6f8f4; --card:#ffffff; --line:#e3ebe3; --tint:#eef3ea;
  --gut:40px; --maxw:1200px; --read:780px;
  --shadow:0 18px 45px -22px rgba(18,47,34,.35);
  --shadow-sm:0 6px 20px -12px rgba(18,47,34,.35);
  --rad:16px;
  font-family:'Inter',system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--body);font-size:17px;line-height:1.7;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:var(--green-600);text-decoration:none}
svg{width:18px;height:18px;flex-shrink:0}
h1,h2,h3,h4{font-family:'Plus Jakarta Sans',sans-serif;color:var(--ink);line-height:1.18;margin:0;font-weight:800;letter-spacing:-.01em}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 var(--gut)}

.rv{animation:rvIn .8s both}
@keyframes rvIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.rv{animation:none}}

.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;font-size:15px;padding:13px 22px;border-radius:999px;border:2px solid transparent;cursor:pointer;transition:transform .15s ease,box-shadow .15s ease,background .15s ease;white-space:nowrap}
.btn:hover{transform:translateY(-2px)}
.btn-gold{background:var(--gold);color:#3a2a00;box-shadow:0 10px 22px -10px rgba(224,167,46,.8)}
.btn-gold:hover{background:var(--gold-dark)}
.btn-ghost{background:transparent;border-color:rgba(255,255,255,.5);color:#fff}
.btn-ghost:hover{background:rgba(255,255,255,.12)}

.hero{background:linear-gradient(180deg,var(--tint),var(--bg));border-bottom:1px solid var(--line)}
.hero .wrap{padding-top:34px;padding-bottom:36px}
.crumb{font-size:13.5px;color:var(--muted);display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:20px}
.crumb a{color:var(--muted)}
.crumb a:hover{color:var(--green-600)}
.crumb .sep{opacity:.5}
.pill{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--line);color:var(--green-700);font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;font-size:12.5px;letter-spacing:.06em;text-transform:uppercase;padding:7px 14px;border-radius:999px;box-shadow:var(--shadow-sm)}
.pill .lf{color:var(--gold-dark)}
h1.title{font-size:clamp(30px,5.2vw,50px);margin:18px 0 0;max-width:20ch}
h1.title .accent{color:var(--green-600)}
.lede{font-size:clamp(17px,2.2vw,20px);color:var(--body);max-width:62ch;margin:16px 0 0;line-height:1.6}
.meta{display:flex;flex-wrap:wrap;gap:10px 22px;align-items:center;margin-top:22px;font-size:14px;color:var(--muted)}
.meta .m{display:inline-flex;align-items:center;gap:8px}
.meta .av{width:34px;height:34px;border-radius:50%;background:var(--green-600);color:#fff;display:grid;place-items:center;font-family:'Plus Jakarta Sans',sans-serif;font-weight:800;font-size:14px}
.meta b{color:var(--ink);font-weight:600}
.meta .dot{width:4px;height:4px;border-radius:50%;background:#c3d1c7}

.feat{max-width:var(--maxw);margin:-8px auto 0;padding:0 var(--gut)}
.feat figure{margin:0}
.feat .frame{border-radius:var(--rad);overflow:hidden;box-shadow:var(--shadow);border:1px solid var(--line);position:relative;background:#dfe7e0}
.feat img{width:100%;height:auto;aspect-ratio:16/9;object-fit:cover}
.feat figcaption{font-size:13.5px;color:var(--muted);margin-top:12px;text-align:center;font-style:italic}

.article{max-width:var(--read);margin:0 auto;padding:48px var(--gut) 20px}
.prose p{margin:0 0 22px}
.prose h2{font-size:clamp(23px,3.4vw,31px);margin:46px 0 6px;padding-top:8px;position:relative}
.prose h2::before{content:"";display:block;width:46px;height:4px;border-radius:3px;background:var(--gold);margin-bottom:16px}
.prose a{font-weight:600;border-bottom:1.5px solid rgba(46,125,79,.35)}
.prose a:hover{border-bottom-color:var(--green-600)}
.prose strong{color:var(--ink)}

/* driver list */
.drivers{list-style:none;margin:6px 0 24px;padding:0}
.drivers li{position:relative;padding:0 0 16px 34px;font-size:16.5px;line-height:1.6}
.drivers li::before{content:"";position:absolute;left:2px;top:8px;width:11px;height:11px;border-radius:50%;border:3px solid var(--green-600)}
.drivers li strong{color:var(--ink)}

/* Quick answer callout */
.tldr{background:linear-gradient(180deg,#fff,var(--tint));border:1px solid var(--line);border-left:5px solid var(--green-600);border-radius:14px;padding:24px 28px;margin:8px 0 30px;box-shadow:var(--shadow-sm)}
.tldr .kick{font-family:'Plus Jakarta Sans',sans-serif;font-weight:800;font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:var(--green-600);display:flex;align-items:center;gap:9px;margin-bottom:10px}
.tldr .kick svg{color:var(--gold-dark)}
.tldr p{margin:0;font-size:16.5px;color:var(--body)}

/* table */
.tbl-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:6px 0 26px;border-radius:14px;border:1px solid var(--line);box-shadow:var(--shadow-sm)}
table.tbl{width:100%;border-collapse:collapse;min-width:560px;background:#fff;font-size:15.5px}
table.tbl thead th{background:var(--green-700);color:#fff;font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;text-align:left;padding:14px 18px;font-size:14px}
table.tbl tbody td{padding:14px 18px;border-top:1px solid var(--line);vertical-align:top;color:var(--body)}
table.tbl tbody tr:nth-child(even){background:#fafcf9}
table.tbl tbody td:first-child{font-weight:700;color:var(--ink);font-family:'Plus Jakarta Sans',sans-serif}
table.tbl tbody tr:hover{background:var(--tint)}

/* FAQ */
.faq{margin:6px 0 8px}
.faq details{background:#fff;border:1px solid var(--line);border-radius:12px;margin:0 0 12px;box-shadow:var(--shadow-sm);overflow:hidden}
.faq summary{list-style:none;cursor:pointer;padding:18px 22px;font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;color:var(--ink);font-size:17px;display:flex;justify-content:space-between;align-items:center;gap:16px}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"+";font-size:24px;color:var(--green-600);font-weight:700;line-height:1;flex:0 0 auto}
.faq details[open] summary::after{content:"\2212"}
.faq details[open] summary{border-bottom:1px solid var(--line)}
.faq .ans{padding:16px 22px 20px;font-size:16px;color:var(--body)}
.faq .ans p{margin:0}

.cta{background:radial-gradient(120% 140% at 12% 0%,var(--green-700),var(--green-900));color:#eaf3ec;margin-top:44px;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;right:-80px;top:-80px;width:320px;height:320px;border-radius:50%;background:radial-gradient(circle,rgba(224,167,46,.22),transparent 62%)}
.cta .wrap{padding-top:56px;padding-bottom:56px;position:relative;z-index:1}
.cta .pill{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.22);color:#fff}
.cta h2{color:#fff;font-size:clamp(26px,4vw,38px);margin:16px 0 0;max-width:20ch}
.cta p{max-width:60ch;margin:16px 0 0;color:#cfe0d3;font-size:17px}
.cta .row{display:flex;flex-wrap:wrap;gap:14px;margin-top:26px}
.cta .chips{display:flex;flex-wrap:wrap;gap:10px 22px;margin-top:26px;font-size:14.5px;color:#dbe8de}
.cta .chips span{display:inline-flex;align-items:center;gap:8px}
.cta .chips svg{color:var(--gold)}

@media(max-width:768px){
  :root{--gut:26px}
  .feat img{aspect-ratio:4/3}
  .article{padding-top:36px}
}
@media(max-width:480px){
  :root{--gut:20px}
  body{font-size:16px}
}
